/* Panel Workspace page shell.
   The 12-column grid rules remain isolated from news and disclosures.
   Legacy DOM selectors remain only until index.html is switched to panel-workspace names. */

#rightPanelContent:has(#rightPanelTabView-panel-workspace:not([hidden])),
#rightPanelContent:has(#rightPanelTabView-dashboard:not([hidden])) {
  overflow: hidden !important;
}

#rightPanelContent:has(#rightPanelTabView-panel-workspace:not([hidden])):has(#rightPanelNews),
#rightPanelContent:has(#rightPanelTabView-dashboard:not([hidden])):has(#rightPanelNews) {
  overflow: auto !important;
}

#rightPanelTabView-panel-workspace,
#rightPanelWorkspace,
#rightPanelTabView-dashboard,
#rightPanelDashboard {
  height: 100%;
  min-height: 0;
}

#rightPanelWorkspace,
#rightPanelDashboard {
  box-sizing: border-box;
  overflow: hidden;
}

#rightPanelTabView-panel-workspace:has(#rightPanelNews),
#rightPanelWorkspace:has(#rightPanelNews),
#rightPanelTabView-dashboard:has(#rightPanelNews),
#rightPanelDashboard:has(#rightPanelNews) {
  height: auto;
  min-height: 100%;
  overflow: visible;
}

